CREATE TABLE default.kafka_events_json_ws (`uuid` UUID, `event` String, `properties` String, `timestamp` DateTime64(6, 'UTC'), `team_id` Int64, `distinct_id` String) ENGINE = Kafka(warpstream_ingestion, kafka_topic_list = 'clickhouse_events_json', kafka_group_name = 'clickhouse_events_json_ws', kafka_format = 'JSONEachRow') SETTINGS kafka_num_consumers = 1, kafka_max_block_size = 100000
